import{_ as t,o as r,c as a,a6 as d}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"跨境SKU批量：从清单到交付目录","description":"","frontmatter":{"id":"cross-border-sku-delivery","title":"跨境SKU批量：从清单到交付目录","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","footwear-skills","ecommerce-image-toolkit","detail-image-workflow"],"platform_rule_ids":["amazon","shopify","shopee"],"order":23.7},"headers":[],"relativePath":"ecommerce/cross-border-sku-delivery.md","filePath":"ecommerce/cross-border-sku-delivery.md"}'),o={name:"ecommerce/cross-border-sku-delivery.md"};function s(i,e,l,c,n,h){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="跨境sku批量-从清单到交付目录" tabindex="-1">跨境SKU批量：从清单到交付目录 <a class="header-anchor" href="#跨境sku批量-从清单到交付目录" aria-label="Permalink to &quot;跨境SKU批量：从清单到交付目录&quot;">​</a></h1><p>先让一项任务完成，再扩展清单。一个任务由“SKU×市场×语言×图片位置×版本”确定；下载后再检查，不把接口回执当成图像可交付。</p><h2 id="第1步-把清单填完整" tabindex="-1">第1步：把清单填完整 <a class="header-anchor" href="#第1步-把清单填完整" aria-label="Permalink to &quot;第1步：把清单填完整&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>示例与作用</th></tr></thead><tbody><tr><td>task_id</td><td>DN01_US_EN_MAIN_v01，稳定定位原任务</td></tr><tr><td>sku</td><td>DN01-W，绑定真实白色版本照片</td></tr><tr><td>market／language</td><td>US／en-US；SG／en-SG等分别记录</td></tr><tr><td>position</td><td>MAIN、DETAIL、A_PLUS或HERO，不能混用</td></tr><tr><td>source_asset</td><td>商品实拍、细节图与准确文字版本</td></tr><tr><td>target_size</td><td>当前确认的宽高；未知先留待填</td></tr><tr><td>status</td><td>planned、generated、reviewed、needs_revision、exported</td></tr><tr><td>result／note</td><td>实际结果文件、未确认事项、返工原因</td></tr></tbody></table><p>虚构练习清单可从<a href="/ai-visual-creation-handbook/ecommerce/cross-border#这次练习准备什么">示例资产目录</a>理解。正式清单里每个SKU都需要真实存在与对应素材，不把母版任意改色当成新商品。</p><h2 id="第2步-先母版-再批量" tabindex="-1">第2步：先母版，再批量 <a class="header-anchor" href="#第2步-先母版-再批量" aria-label="Permalink to &quot;第2步：先母版，再批量&quot;">​</a></h2><p>复制<a href="/ai-visual-creation-handbook/prompts/P19">P19 SKU批量计划</a>，固定商品处理、色彩、背景、文字层与命名。先核对一个SKU的一张图，再扩展其他位置。场景与主图不能共享错误的宣传字样；跨语言只改获准的文字层与布局。</p><p>稳定的图像步骤可进入ComfyUI节点，精准文字与最终合成仍由图层／页面编辑器负责。并发、重试或服务接口由实际使用工具管理；不要为完成清单重复提交未知状态的原任务。</p><h2 id="第3步-中断与返工" tabindex="-1">第3步：中断与返工 <a class="header-anchor" href="#第3步-中断与返工" aria-label="Permalink to &quot;第3步：中断与返工&quot;">​</a></h2><p>收到超时先查原任务ID和结果是否已经出现。商品结构不对只返工对应SKU；译文错误只改对应语言；主题裁切不合适只重排该位置。保留前一版，记录改变了哪项条件。</p><h2 id="第4步-交付与状态" tabindex="-1">第4步：交付与状态 <a class="header-anchor" href="#第4步-交付与状态" aria-label="Permalink to &quot;第4步：交付与状态&quot;">​</a></h2><p>目录按市场／SKU／位置组织，图片名带语言与版本。另附事实表、准确文案、媒体顺序、源文件和检查表；只交真实存在的文件，不把计划路径当产物。使用<a href="/ai-visual-creation-handbook/prompts/P20">P20交付检查</a>得到问题位置和具体修正。</p><p>“exported”表示文件已经导出，不等于后台已上传；“published”只有查看实际平台状态后才填写。本项目尚未执行新SKU批量生成与平台上传。</p>',13)])])}const u=t(o,[["render",s]]);export{m as __pageData,u as default};
